#!/bin/bash
# Mod-Agent Java launcher (Linux/macOS). Generated by `java -jar <agent>.jar setup-badlion`.
# Reads java.conf beside this file, adds the agent as the LAST JVM option (so it loads after
# any native agent already on the command line), then execs the real Java with the same PID.
# Version/help probes pass through unchanged. Values in java.conf are literal, never evaluated.

fail() { printf '[Mod-Agent Launcher] %s\n' "$1" >&2; exit 126; }
trim() {
    local value=$1
    value=${value#"${value%%[![:space:]]*}"}
    value=${value%"${value##*[![:space:]]}"}
    printf '%s' "$value"
}

self=${BASH_SOURCE[0]}
case $self in */*) ;; *) self=$(command -v -- "$self") || fail "Cannot resolve launcher path";; esac
dir=$(cd -P -- "$(dirname -- "$self")" && pwd -P) || fail "Cannot resolve launcher directory"
self=$dir/$(basename -- "$self")
conf=$dir/java.conf
[ -f "$conf" ] && [ -r "$conf" ] || fail "Cannot read java.conf beside the launcher"

runtime='' agent='' config='' log=''
options=()
while IFS= read -r line || [ -n "$line" ]; do
    line=$(trim "$line")
    case $line in ''|'#'*) continue;; esac
    case $line in *=*) ;; *) fail "Configuration lines must use key=value";; esac
    key=$(trim "${line%%=*}")
    value=$(trim "${line#*=}")
    [ -n "$value" ] || fail "Empty configuration value"
    case $key in
        runtime) [ -z "$runtime" ] || fail "Duplicate configuration key"; runtime=$value;;
        agent)   [ -z "$agent" ]   || fail "Duplicate configuration key"; agent=$value;;
        config)  [ -z "$config" ]  || fail "Duplicate configuration key"; config=$value;;
        log)     [ -z "$log" ]     || fail "Duplicate configuration key"; log=$value;;
        vm_option)
            case $value in -D?*) ;; *) fail "vm_option must be a system property (-D...)";; esac
            options+=("$value");;
        *) fail "Unknown configuration key";;
    esac
done < "$conf"

case $runtime in /*) ;; *) fail "runtime= must be the absolute bin directory of the real Java";; esac
real=$runtime/java
[ -f "$real" ] && [ -x "$real" ] || fail "runtime= does not contain an executable java"
[ "$real" -ef "$self" ] && fail "runtime= points back to this launcher"

log_launch() {
    [ -n "$log" ] || return 0
    case $log in /*) ;; *) fail "log= must be an absolute file path";; esac
    [ -L "$log" ] && return 0
    ( umask 077; printf '%s pid=%s agent_added=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$$" "$1" >> "$log" ) 2>/dev/null
    return 0
}

is_probe() {
    [ $# -eq 0 ] && return 0
    while [ $# -gt 0 ]; do
        case $1 in
            -version|--version|-fullversion|-help|--help|'-?'|-X|--help-extra) return 0;;
            -cp|-classpath|--class-path|-p|--module-path) [ $# -gt 1 ] && shift;;
            -jar|-m|--module|--module=*) return 1;;
            -*) ;;
            *) return 1;;
        esac
        shift
    done
    return 1
}

if is_probe "$@"; then
    log_launch false
    exec "$real" "$@"
fi

[ -n "$agent" ] || fail "agent= is required for game launches"
case $agent in /*) ;; *) fail "agent= must name an absolute JAR path";; esac
[ -f "$agent" ] && [ -r "$agent" ] || fail "agent= must name a readable JAR"
case $agent in *=*) fail "Agent JAR path cannot contain '='";; esac
if [ -n "$config" ]; then
    case $config in /*) ;; *) fail "config= must name an absolute file path";; esac
    [ -f "$config" ] && [ -r "$config" ] || fail "config= must name a readable file"
    agent_option="-javaagent:$agent=$config"
else
    agent_option="-javaagent:$agent"
fi
owned=("$agent_option" ${options[@]+"${options[@]}"})

forwarded=()
boundary=0
operand=0
for argument in "$@"; do
    if [ $boundary -eq 1 ] || [ $operand -eq 1 ]; then
        operand=0
        forwarded+=("$argument")
        continue
    fi
    duplicate=0
    for option in "${owned[@]}"; do [ "$argument" = "$option" ] && duplicate=1; done
    [ $duplicate -eq 1 ] && continue
    case $argument in
        -javaagent:"$agent"|-javaagent:"$agent"=*) fail "Conflicting configuration for this Java agent";;
        -cp|-classpath|--class-path|-p|--module-path) operand=1;;
        -jar|-m|--module|--module=*) boundary=1;;
        -*) ;;
        *) boundary=1;;
    esac
    [ $boundary -eq 1 ] && forwarded+=("${owned[@]}")
    forwarded+=("$argument")
done
[ $boundary -eq 0 ] && forwarded+=("${owned[@]}")

log_launch true
exec "$real" "${forwarded[@]}"
